# File: backend/app/core/rate_limit.py | take_token
def take_token(key: str, capacity: int, period_seconds: int, what: str) -> Decision:
    """
    Token bucket: allow `capacity` requests per `period_seconds` (refilling steadily), per `key`.
    `what` names the thing being limited in the message ("questions", "uploads").
    """
    try:
        bucket, _ = _scripts()
        allowed, wait, *_ = bucket(keys=[key], args=[capacity, capacity / period_seconds])
    except (redis.RedisError, OSError):
        logger.warning("Rate limiter: Redis is unavailable, letting the request through", exc_info=True)
        return Decision(allowed=True)

    if int(allowed) == 1:
        return Decision(allowed=True, limit=capacity)

    seconds = max(1, math.ceil(float(wait)))
    return Decision(
        allowed=False,
        retry_after=seconds,
        limit=capacity,
        message=f"Too many {what}. Try again in {seconds} seconds.",
    )

# File: backend/app/generation/orchestrator.py | get_context_builder, count_tokens, trim_history
# Matches "[1]", "[12]" and also "[1, 2]"
CITATION_GROUP = re.compile(r"\[(\d+(?:\s*,\s*\d+)*)\]")


@lru_cache(maxsize=1)
def get_context_builder() -> ContextBuilder:
    """Created on first use, so importing this module does no work (the tokenizer loads lazily)."""
    return ContextBuilder()


def count_tokens(text: str) -> int:
    """Approximate token count (same tokenizer the context budget uses)."""
    return len(get_context_builder().encoding.encode(text))


def trim_history(
    history: list[tuple[str, str]],
    max_tokens: int = HISTORY_MAX_TOKENS,
) -> list[tuple[str, str]]:
    """
    LAST-RESORT safety net: keeps the most recent messages that fit in max_tokens.
    Normally older messages are summarized (see summary.py) long before this
    drops anything; this only matters if summarizing keeps failing.
    The result always starts with a user message (some providers, e.g. Gemini,
    reject a conversation that starts with the assistant).
    """
    kept = []
    total = 0
    for role, content in reversed(history):
        tokens = count_tokens(content)
        if total + tokens > max_tokens:
            break
        kept.append((role, content))
        total += tokens
    kept.reverse()

    while kept and kept[0][0] != "user":
        kept.pop(0)
    return kept

