def take_token(key: str, capacity: int, period_seconds: int, what: str) -> Decision:
    """
    Token bucket: allow `capacity` requests per `period_seconds` (refilling steadily), per `key`.
    `what` names the thing being limited in the message ("questions", "uploads").
    """
    try:
        bucket, _ = _scripts()
        allowed, wait, *_ = bucket(keys=[key], args=[capacity, capacity / period_seconds])
    except (redis.RedisError, OSError):
        logger.warning("Rate limiter: Redis is unavailable, letting the request through", exc_info=True)
        return Decision(allowed=True)

    if int(allowed) == 1:
        return Decision(allowed=True, limit=capacity)

    seconds = max(1, math.ceil(float(wait)))
    return Decision(
        allowed=False,
        retry_after=seconds,
        limit=capacity,
        message=f"Too many {what}. Try again in {seconds} seconds.",
    )

// File: frontend/src/features/documents/useUploads.js | useUploads.discard
  // The chip's X.
  const discard = useCallback(
    async (key) => {
      const item = itemsRef.current.find((i) => i.key === key)
      if (!item) return
      if (!item.documentId) {
        // never reached the library (refused, failed to upload) or still on its way: cancel and forget it
        cancelled.current.add(key)
        controllers.current.get(key)?.abort()
        remove(key)
        return
      }
      patch(key, { status: 'deleting' })
      try {
        await deleteDocument(item.documentId)
        remove(key)
      } catch (error) {
        if (error.code === 'not_found') remove(key)
        else patch(key, { status: 'error', error: `Could not remove it: ${error.message}` })
      }
    },
    [patch, remove],
  )

